<?php require __DIR__.'/../app/bootstrap.php'; if(!empty($_SESSION['admin_id'])){header('Location: '.url('admin/index.php'));exit;} $error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$s=db()->prepare('SELECT id,name,password_hash FROM admins WHERE email=? LIMIT 1');$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a && password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: '.url('admin/index.php'));exit;}$error='Email or password is incorrect.';} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login — NEXT TECH</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-login"><form method="post" class="login-card"><a class="wordmark" href="<?=e(url('index.php'))?>"><span>NEXT</span> <b>TECH</b></a><h1>Admin Sign In</h1><?php if($error): ?><p class="form-error"><?=e($error)?></p><?php endif; ?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn btn-primary">Sign In</button></form></body></html>
